// Registers the docs offline cache (dist/sw.js, generated by scripts/perf/postbuild.mjs) once the page
// is idle. Used by the docs pages; the site's own pages do the same in src/lib/prefetch-docs.js.
(function () {
  var c = navigator.connection
  if (!('serviceWorker' in navigator) || (c && (c.saveData || /2g/.test(c.effectiveType || '')))) return
  var go = function () { navigator.serviceWorker.register('/sw.js').catch(function () {}) }
  var idle = function () { (window.requestIdleCallback || function (f) { setTimeout(f, 1500) })(go) }
  if (document.readyState === 'complete') idle()
  else window.addEventListener('load', idle, { once: true })
})()
